const G = GAMES[GAME];

const MATCH_MS = 5400 * 1000;

// Population by UTC hour for a European-evening server. Interpolated by minute.
const CURVE = [
  55, 40, 28, 18, 12, 8, 7, 9, 12, 16, 22, 28, 34, 40, 48, 56, 66, 78, 90, 98, 100, 96, 86, 70,
];

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function population(now) {
  const d = new Date(now);
  const h = d.getUTCHours();
  const m = d.getUTCMinutes();
  const a = CURVE[h];
  const b = CURVE[(h + 1) % 24];
  let p = a + ((b - a) * m) / 60;
  const dow = d.getUTCDay();
  if (dow === 5 || dow === 6) p *= 1.06;
  if (dow === 0 && h >= 20) p *= 0.94;
  // Slow drift so two readings ten minutes apart are not identical.
  p += Math.sin(now / (13 * 60_000)) * 4 + Math.sin(now / (37 * 60_000)) * 3;
  return Math.max(0, Math.min(100, Math.round(p)));
}

function matchState(now) {
  const idx = Math.floor(now / MATCH_MS);
  const elapsed = Math.floor((now % MATCH_MS) / 1000);
  const [layer, mapName, gameMode, attacker, alliedFaction, axisFaction] =
    G.layers[idx % G.layers.length];
  const phase = elapsed / 5400;
  const rnd = mulberry32(idx * 7919);
  const swing = rnd() * 2 - 1; // which way this match is going
  let allied, axis;
  if (attacker) {
    // Score counts sectors held out of five; the attacker starts at zero.
    const taken = Math.min(5, Math.floor(phase * (3.5 + rnd() * 3)));
    allied = attacker === "allied" ? taken : 5 - taken;
    axis = 5 - allied;
  } else {
    allied = Math.max(
      1,
      Math.min(4, Math.round(2.5 + swing * phase * 2.2 + Math.sin(phase * 6 + swing) * 0.5)),
    );
    axis = 5 - allied;
  }
  const players = population(now);
  const alliedCount = Math.min(players, Math.max(0, Math.round(players / 2 + Math.sin(idx) * 1.5)));
  return {
    idx,
    elapsed,
    remaining: 5400 - elapsed,
    layer,
    mapName,
    gameMode,
    alliedFaction,
    axisFaction,
    phase,
    allied,
    axis,
    players,
    alliedCount,
    axisCount: players - alliedCount,
    alliedMorale: Math.max(200, 1000 - Math.round(phase * (300 + rnd() * 400))),
    axisMorale: Math.max(200, 1000 - Math.round(phase * (300 + rnd() * 400))),
    queue: players >= 98 ? 2 + Math.floor(rnd() * 5) : 0,
  };
}

const NAMES =
  "Redleg Bandit Pinetree Vandal Ghost_Rider Mongoose Boomer Cutter Sixgun Tango Wraith Shaky Drifter Ratchet Longshot Deacon Pilgrim Rooster Turbo Judge Kilo Chalk Bullet Hammer Stubs Lucky Doc_Holliday Cobra Sarge Wick Hooper Rex Ranger_Bob Tinman Dutch Jinx Hawk Sable Trip Slim Nomad Skunk Buzz Grumpy Tex Reaper Otter Cooper Weasel Ponyboy Falcon Bravo_Six Mudcat Spanner Stitch Goose Pilot_Pete Gravy Fuse Domino Crank Swift Scout Zulu Padre Rebel Ace Dozer Tiny Mack Blaze Fritz Duke Rhino Sparks Snake Whiskey Torch Pike Cub".split(
    " ",
  );
const SQUADS = "ABLE BAKER CHARLIE DOG EASY FOX GEORGE HOW ITEM JIG KING LOVE".split(" ");

function buildTeam(rng, teamField, count, phase, hasAir, used) {
  const out = [];
  const pick = () => {
    for (;;) {
      const n = NAMES[Math.floor(rng() * NAMES.length)];
      if (!used.has(n)) {
        used.add(n);
        return n;
      }
      if (used.size >= NAMES.length) return "Player" + Math.floor(rng() * 1000);
    }
  };
  let left = count;
  let sq = 0;
  const add = (role, platoon, idx) => {
    if (left <= 0) return;
    left--;
    const level = 1 + Math.floor(Math.pow(rng(), 1.7) * 250);
    const k = Math.floor(rng() * 26 * phase);
    const d = Math.floor(rng() * 12 * phase);
    out.push({
      name: pick(),
      clanTag: G.tags[Math.floor(rng() * G.tags.length)],
      iD: "demo-" + out.length,
      platform:
        rng() < 0.7
          ? "EPlatformFamily::Steam"
          : rng() < 0.5
            ? "EPlatformFamily::PS5"
            : "EPlatformFamily::XboxSeries",
      eosId: "demo-" + out.length,
      steamId: null,
      level,
      team: teamField,
      role,
      platoon,
      platoonIndex: idx,
      loadout: "Standard",
      stats: {
        deaths: d,
        infantryKills: k,
        vehicleKills: role === 12 || role === 11 ? Math.floor(rng() * 3 * phase) : 0,
        teamKills: rng() < 0.08 ? 1 : 0,
        vehiclesDestroyed: 0,
      },
      scoreData: {
        cOMBAT: k * 10 + Math.floor(rng() * 40 * phase),
        offense: Math.floor(rng() * 260 * phase),
        defense: Math.floor(rng() * 220 * phase),
        support: Math.floor(rng() * 180 * phase),
      },
      worldPosition: {
        x: Math.floor(rng() * 200000),
        y: Math.floor(rng() * 200000),
        z: Math.floor(rng() * 3000),
      },
    });
  };
  if (count >= 20) add(G.commander, "", 0);
  if (count >= 12) {
    const idx = sq++;
    for (const r of G.armor.slice(0, count >= 30 ? 3 : 2)) add(r, "ARMOR", idx);
  }
  if (G.mortar && count >= 18) {
    const idx = sq++;
    for (const r of G.mortar) add(r, "MORTAR", idx);
  }
  if (count >= 30) {
    const idx = sq++;
    for (const r of G.recon) add(r, "RECON", idx);
  }
  if (G.air && hasAir && count >= 24) {
    const idx = sq++;
    for (const r of G.air) add(r, "AIR", idx);
  }
  const loose = count >= 15 ? Math.floor(count * 0.05) : 0;
  let si = 0;
  while (left > loose && si < SQUADS.length) {
    const idx = sq++;
    const name = SQUADS[si++];
    const size = Math.min(6, left - loose);
    add(G.leader, name, idx);
    for (let i = 1; i < size; i++) add(G.inf[Math.floor(rng() * G.inf.length)], name, idx);
  }
  while (left > 0) add(G.inf[Math.floor(rng() * G.inf.length)], "", 0);
  return out;
}

function dynamicSession(now) {
  const m = matchState(now);
  return {
    serverName: G.serverName,
    mapName: m.mapName,
    mapId: m.layer,
    gameMode: m.gameMode,
    remainingMatchTime: m.remaining,
    matchTime: 5400,
    alliedScore: m.allied,
    axisScore: m.axis,
    playerCount: m.players,
    alliedPlayerCount: m.alliedCount,
    axisPlayerCount: m.axisCount,
    maxPlayerCount: 100,
    queueCount: m.queue,
    maxQueueCount: 6,
    vipQueueCount: 0,
    maxVipQueueCount: 2,
    alliedFaction: m.alliedFaction,
    axisFaction: m.axisFaction,
    alliedMorale: m.alliedMorale,
    axisMorale: m.axisMorale,
    initialMorale: 1000,
  };
}

function dynamicPlayers(now) {
  const m = matchState(now);
  // Reseed every five minutes: names drift as people come and go, but a
  // 20-second refresh sees the same platoon.
  const seed = m.idx * 104729 + Math.floor(now / (5 * 60_000));
  const rng = mulberry32(seed);
  // One name pool across both teams: nobody is on both sides at once.
  const used = new Set();
  return {
    players: [
      ...buildTeam(rng, m.alliedFaction, m.alliedCount, m.phase, true, used),
      ...buildTeam(rng, m.axisFaction, m.axisCount, m.phase, false, used),
    ],
  };
}

function dynamicRotation(now) {
  const m = matchState(now);
  return {
    currentIndex: m.idx % G.layers.length,
    mAPS: G.layers.map(([layer, name, gameMode], position) => ({
      name,
      gameMode,
      timeOfDay: /night/i.test(layer) ? "Night" : "Day",
      iD: `/Game/Maps/${layer}`,
      position,
    })),
  };
}

const CONFIG = () => ({
  serverName: DYNAMIC ? G.serverName : STATIC_SESSION.serverName,
  buildNumber: 1042,
  buildRevision: 7,
  supportedPlatforms: ["EPlatform::PC_Steam", "EPlatform::PS5", "EPlatform::Xbox_SeriesX"],
  passwordProtected: false,
});

const INFO = {
  session: () => (DYNAMIC ? dynamicSession(Date.now()) : STATIC_SESSION),
  players: () => (DYNAMIC ? dynamicPlayers(Date.now()) : STATIC_PLAYERS),
  maprotation: () => (DYNAMIC ? dynamicRotation(Date.now()) : STATIC_ROTATION),
  serverconfig: CONFIG,
};

// ---- wire -------------------------------------------------------------------

function xor(buf, key) {
  if (!key) return buf;
  const out = Buffer.allocUnsafe(buf.length);
  for (let i = 0; i < buf.length; i++) out[i] = buf[i] ^ key[i % key.length];
  return out;
}

const server = net.createServer((sock) => {
  let key = null;
  let token = null;
  let buf = Buffer.alloc(0);

  const send = (id, obj) => {
    const body = xor(Buffer.from(JSON.stringify(obj), "utf8"), key);
    const h = Buffer.allocUnsafe(12);
    h.writeUInt32LE(MAGIC, 0);
    h.writeUInt32LE(id, 4);
    h.writeUInt32LE(body.length, 8);
    // Split the write so the client has to reassemble a frame — but keep the
    // three pieces contiguous on the socket, as a real server would.
    sock.write(h);
    sock.write(body.subarray(0, 5));
    sock.write(body.subarray(5));
  };

  const reply = (id, req, statusCode, contentBody, statusMessage = "OK") =>
    send(id, { name: req.name, version: req.version, statusCode, statusMessage, contentBody });

  sock.on("data", (d) => {
    buf = Buffer.concat([buf, d]);
    for (;;) {
      if (buf.length < 12) return;
      if (buf.readUInt32LE(0) !== MAGIC) {
        sock.destroy();
        return;
      }
      const id = buf.readUInt32LE(4);
      const len = buf.readUInt32LE(8);
      if (len > 1_000_000) {
        sock.destroy();
        return;
      }
      if (buf.length < 12 + len) return;
      const raw = xor(buf.subarray(12, 12 + len), key);
      buf = buf.subarray(12 + len);
      let req;
      try {
        req = JSON.parse(raw.toString("utf8"));
      } catch {
        sock.destroy();
        return;
      }
      if (req.name === "ServerConnect") {
        key = crypto.randomBytes(16);
        // Key goes out in the clear; everything after is XOR'd.
        const body = Buffer.from(
          JSON.stringify({
            name: "ServerConnect",
            version: 2,
            statusCode: 200,
            statusMessage: "OK",
            contentBody: key.toString("base64"),
          }),
        );
        const h = Buffer.allocUnsafe(12);
        h.writeUInt32LE(MAGIC, 0);
        h.writeUInt32LE(id, 4);
        h.writeUInt32LE(body.length, 8);
        sock.write(Buffer.concat([h, body]));
        continue;
      }
      if (req.name === "Login") {
        if (req.contentBody !== PASSWORD) {
          reply(id, req, 401, "", "Unauthorized");
          continue;
        }
        token = crypto.randomBytes(12).toString("hex");
        reply(id, req, 200, token);
        continue;
      }
      if (req.authToken !== token) {
        reply(id, req, 401, "", "Unauthorized");
        continue;
      }
      if (req.name === "GetServerInformation") {
        let q;
        try {
          q = JSON.parse(req.contentBody);
        } catch {
          reply(id, req, 400, "", "Bad Request");
          continue;
        }
        const fn = INFO[q?.Name];
        if (!fn) reply(id, req, 400, "", "Bad Request");
        else reply(id, req, 200, JSON.stringify(fn()));
        continue;
      }
      reply(id, req, 400, "", "Unknown command");
    }
  });
  sock.on("error", () => {});
  // A client that connects and says nothing is dropped after a while.
  sock.setTimeout(60_000, () => sock.destroy());
});

server.listen(PORT, HOST, () => {
  console.log(
    `fake hllv rcon on ${HOST}:${PORT} ${DYNAMIC ? `(dynamic demo, ${GAME})` : "(static fixtures)"} pw=${PASSWORD === "hunter2" ? "hunter2" : "[set]"}`,
  );
});
